/**
 * PROTOTYPE — throwaway. Question: should the AI-generated hero banner be
 * replaced by a layered vector redraw with a slight scroll parallax and ambient
 * motion?
 *
 * Three variants on the existing `/` route, switchable with `?variant=` or the
 * floating bar (← / → keys too): `lines` (ink outlines), `fills` (tonal fills,
 * no outlines) and `original` (the current AI image, for comparison). `?amp=`
 * sets the parallax strength in scene units (default 60; the bar has − / +
 * buttons).
 *
 * The scene itself is generated by generate_scene.py into
 * hero-scene.prototype.svg.
 */
import { useEffect, useRef, useState } from "react";

import "./hero-scene.prototype.css";
import sceneSvg from "./hero-scene.prototype.svg?raw";

const VARIANTS = [
    { key: "lines", label: "Ink lines" },
    { key: "fills", label: "Tonal fills, no lines" },
    { key: "original", label: "Original (AI image)" },
] as const;
type VariantKey = (typeof VARIANTS)[number]["key"];

function readParams(): { variant: VariantKey; amp: number } {
    const params = new URLSearchParams(window.location.search);
    const v = params.get("variant");
    const variant = VARIANTS.find((x) => x.key === v)?.key ?? "lines";
    const amp = Number(params.get("amp") ?? 60);
    return { variant, amp: Number.isFinite(amp) ? amp : 60 };
}

function writeParam(key: string, value: string) {
    const url = new URL(window.location.href);
    url.searchParams.set(key, value);
    window.history.replaceState(window.history.state, "", url);
}

export function HeroScenePrototype({ originalSrc }: { originalSrc: string }) {
    const [{ variant, amp }, setState] = useState(readParams);
    const ref = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const el = ref.current;
        if (!el) return;
        let frame = 0;
        const update = () => {
            frame = 0;
            const rect = el.getBoundingClientRect();
            const top = rect.top + window.scrollY;
            // 0 with the page at the top, 1 once the hero has scrolled out of view
            // `?s=` pins the progress, to inspect the extreme without scrolling
            const pinned = new URLSearchParams(window.location.search).get("s");
            const s = pinned
                ? Number(pinned)
                : Math.min(
                      1,
                      Math.max(0, window.scrollY / (top + rect.height)),
                  );
            el.style.setProperty("--s", s.toFixed(4));
        };
        const onScroll = () => {
            if (!frame) frame = requestAnimationFrame(update);
        };
        update();
        window.addEventListener("scroll", onScroll, { passive: true });
        window.addEventListener("resize", onScroll);
        return () => {
            window.removeEventListener("scroll", onScroll);
            window.removeEventListener("resize", onScroll);
            cancelAnimationFrame(frame);
        };
    }, [variant]);

    const setVariant = (v: VariantKey) => {
        writeParam("variant", v);
        setState((s) => ({ ...s, variant: v }));
    };
    const setAmp = (a: number) => {
        writeParam("amp", String(a));
        setState((s) => ({ ...s, amp: a }));
    };

    return (
        <>
            {variant === "original" ? (
                <img
                    src={originalSrc}
                    alt="Energetica game interface showing power grid management"
                    className="w-full h-auto"
                />
            ) : (
                <div
                    ref={ref}
                    className={`hs hs-${variant}`}
                    style={{ "--amp": amp } as React.CSSProperties}
                    dangerouslySetInnerHTML={{ __html: sceneSvg }}
                />
            )}
            <PrototypeSwitcher
                variant={variant}
                onVariant={setVariant}
                amp={amp}
                onAmp={setAmp}
            />
        </>
    );
}

function PrototypeSwitcher({
    variant,
    onVariant,
    amp,
    onAmp,
}: {
    variant: VariantKey;
    onVariant: (v: VariantKey) => void;
    amp: number;
    onAmp: (a: number) => void;
}) {
    const index = VARIANTS.findIndex((v) => v.key === variant);
    const cycle = (step: number) =>
        onVariant(
            VARIANTS[(index + step + VARIANTS.length) % VARIANTS.length]!.key,
        );

    useEffect(() => {
        const onKey = (e: KeyboardEvent) => {
            const t = e.target as HTMLElement | null;
            if (t?.closest("input, textarea, [contenteditable]")) return;
            if (e.key === "ArrowLeft") cycle(-1);
            if (e.key === "ArrowRight") cycle(1);
        };
        window.addEventListener("keydown", onKey);
        return () => window.removeEventListener("keydown", onKey);
    });

    const button = "px-2 py-1 rounded-full hover:bg-white/15";
    return (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 flex items-center gap-2 rounded-full bg-black/85 px-3 py-1.5 text-sm text-white shadow-xl font-mono">
            <span className="text-xs opacity-60">PROTOTYPE</span>
            <button type="button" className={button} onClick={() => cycle(-1)}>
                ←
            </button>
            <span className="min-w-56 text-center">
                {variant} — {VARIANTS[index]?.label}
            </span>
            <button type="button" className={button} onClick={() => cycle(1)}>
                →
            </button>
            <span className="mx-1 h-4 w-px bg-white/30" />
            <span className="text-xs opacity-60">parallax</span>
            <button
                type="button"
                className={button}
                onClick={() => onAmp(Math.max(0, amp - 20))}
            >
                −
            </button>
            <span className="w-8 text-center">{amp}</span>
            <button
                type="button"
                className={button}
                onClick={() => onAmp(amp + 20)}
            >
                +
            </button>
        </div>
    );
}
